;;
; @file   script_07.asm
; @brief  Building NPC schedule variant for the days on which strcDialogDisplay.mapFlags has bit $0008 set (a bad-weather
;         flag; meaning not named in the sources). Slots 0-7 mirror script_01 for the mayor's house, church, flower shop,
;         tool shop, restaurant, fortune teller, animal shop and carpenter's house. Confidence: medium (derived from the
;         dialogs, flags and callers).
; @bank   $B3   (AI byte code; script id $07, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see    script_01 script_04 script_06 script_08 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_07.asm"
 
